var orders = await dbContext.Orders
    .Include(o => o.OrderItems)
    .Include(o => o.Payments)
    .Where(o => o.Id == orderId)
    .FirstOrDefaultAsync();

// SQL joins OrderItems and Payments.
// If order has 10 items and 3 payments, you get 30 rows
// but only 13 actual entities.

var orders = await dbContext.Orders
    .Include(o => o.OrderItems)
    .Include(o => o.Payments)
    .AsSplitQuery()
    .Where(o => o.Id == orderId)
    .FirstOrDefaultAsync();

// Generates 3 SQL queries:
// 1. SELECT * FROM Orders WHERE Id = @p0
// 2. SELECT * FROM OrderItems WHERE OrderId = @p0
// 3. SELECT * FROM Payments WHERE OrderId = @p0
